import React, { forwardRef } from 'react';
import styled from 'styled-components';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { _isStringChildren } from '../../core/utils/is-string-children.js';
import { getTextStyle } from '../../core/utils/styles/text-styles.js';
import { Heading } from '../../typography/Heading.js';

//#region Typings
/** Accepted properties for the TitleBar Title */
export interface TitleBarTitleProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the TitleBar Title slot. */
  children: React.ReactNode;
}
//#endregion

const StyledTitle = /* @__PURE__ */ styled('div')({
  ...getTextStyle('base'),
});
//#endregion

/** TitleBar Title component */
export const Title = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  TitleBarTitleProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: TitleBarTitleProps = props;
  const childIsText = _isStringChildren(props.children);

  return (
    <StyledTitle
      ref={forwardedRef}
      className={consumerClassName}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {childIsText ? (
        <Heading level={3} as="h2">
          {children}
        </Heading>
      ) : (
        children
      )}
    </StyledTitle>
  );
});
